package com.zoro.zoromart.service;
import java.util.Locale;
/** Deterministic FAQ provider for local development and offline demonstrations. */
public class MockChatProvider implements ChatProvider {public String getReply(String message,String context){String m=message.toLowerCase(Locale.ROOT);if(m.contains("cart"))return "Open Cart, check quantities, and continue to Checkout when ready.";if(m.contains("payment")||m.contains("checkout"))return "ZoroMart uses a mock payment confirmation for this academic demo; no real payment is collected.";if(m.contains("order"))return "Sign in and open Order History to view your order status. Sellers can view incoming orders in Seller Studio.";if(m.contains("review"))return "Reviews are accepted only for products in an order whose status is Delivered.";if(m.contains("seller")||m.contains("sell"))return "Create an account with the Seller role to manage your own product listings.";if(m.contains("stock"))return "Product availability is based on the stock quantity shown on the listing.";if(m.contains("return"))return "This academic prototype does not process real returns. Contact the seller/admin for demo order issues.";if(m.contains("price"))return "The price shown on the product listing is the price used at checkout.";return "Browse Products and use keyword search or the category filter to find items.";}}
